const http = require('http');
const https = require('https');
const crypto = require('crypto');
const { URL } = require('url');

// Background job worker that processes tasks from internal queue
// and authenticates to downstream services using NTLM/Negotiate

class NTLMAuthContext {
  constructor(domain, username, workstation) {
    this.domain = domain;
    this.username = username;
    this.workstation = workstation;
    this.negotiateFlags = 0xe2088235;
    this.sessionKey = null;
  }

  createType1Message() {
    const signature = Buffer.from('NTLMSSP\0');
    const type = Buffer.alloc(4);
    type.writeUInt32LE(1, 0);
    const flags = Buffer.alloc(4);
    flags.writeUInt32LE(this.negotiateFlags, 0);
    return Buffer.concat([signature, type, flags]).toString('base64');
  }

  createType3Message(challenge, targetInfo) {
    const signature = Buffer.from('NTLMSSP\0');
    const type = Buffer.alloc(4);
    type.writeUInt32LE(3, 0);
    const response = this._computeResponse(challenge, targetInfo);
    return Buffer.concat([signature, type, response]).toString('base64');
  }

  _computeResponse(challenge, targetInfo) {
    const timestamp = Buffer.alloc(8);
    const now = BigInt(Date.now()) * 10000n + 116444736000000000n;
    timestamp.writeBigUInt64LE(now, 0);
    const clientChallenge = crypto.randomBytes(8);
    const blob = Buffer.concat([Buffer.from([0x01, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00]), timestamp, clientChallenge, Buffer.alloc(4), targetInfo]);
    return blob;
  }
}

class ServiceAuthenticator {
  constructor(config) {
    this.config = config;
    this.authCache = new Map();
    this.pendingChallenges = new Map();
  }

  async authenticate(serviceUrl, credentials) {
    const parsedUrl = new URL(serviceUrl);
    const cacheKey = `${parsedUrl.host}:${credentials.username}`;

    if (this.authCache.has(cacheKey)) {
      const cached = this.authCache.get(cacheKey);
      if (Date.now() - cached.timestamp < 300000) {
        return cached.token;
      }
    }

    const ntlmCtx = new NTLMAuthContext(credentials.domain, credentials.username, credentials.workstation);
    const type1 = ntlmCtx.createType1Message();

    const challengeResponse = await this._sendNegotiate(serviceUrl, type1);

    if (challengeResponse.statusCode === 401 && challengeResponse.headers['www-authenticate']) {
      const authHeader = challengeResponse.headers['www-authenticate'];
      const type2Data = this._extractType2(authHeader);

      if (type2Data) {
        const type3 = ntlmCtx.createType3Message(type2Data.challenge, type2Data.targetInfo);
        const authResult = await this._sendAuthenticate(serviceUrl, type3, challengeResponse);

        if (authResult.statusCode === 200) {
          this.authCache.set(cacheKey, { token: authResult.headers['x-auth-token'], timestamp: Date.now() });
          return authResult.headers['x-auth-token'];
        }
      }
    }
    throw new Error('NTLM authentication failed');
  }

  async _sendNegotiate(serviceUrl, type1Message) {
    return this._makeRequest(serviceUrl, { 'Authorization': `Negotiate ${type1Message}` });
  }

  async _sendAuthenticate(serviceUrl, type3Message, priorResponse) {
    const connectionId = priorResponse.headers['x-connection-id'];
    return this._makeRequest(serviceUrl, { 
      'Authorization': `Negotiate ${type3Message}`,
      'X-Connection-Id': connectionId
    });
  }

  _extractType2(header) {
    const match = header.match(/Negotiate\s+(.+)/);
    if (!match) return null;
    const decoded = Buffer.from(match[1], 'base64');
    if (decoded.slice(0, 7).toString() !== 'NTLMSSP') return null;
    const challenge = decoded.slice(24, 32);
    const targetInfo = decoded.slice(40);
    return { challenge, targetInfo };
  }

  _makeRequest(url, headers) {
    return new Promise((resolve, reject) => {
      const parsedUrl = new URL(url);
      const options = { hostname: parsedUrl.hostname, port: parsedUrl.port, path: parsedUrl.pathname, method: 'GET', headers };
      const client = parsedUrl.protocol === 'https:' ? https : http;
      const req = client.request(options, (res) => {
        let body = '';
        res.on('data', (chunk) => body += chunk);
        res.on('end', () => { res.body = body; resolve(res); });
      });
      req.on('error', reject);
      req.end();
    });
  }
}

class JobWorker {
  constructor(config) {
    this.authenticator = new ServiceAuthenticator(config);
    this.config = config;
    this.channelBindingEnabled = false;
  }

  async processJob(job) {
    const targetService = this._resolveServiceEndpoint(job.serviceId);
    const credentials = this._getServiceCredentials(job.serviceId);

    try {
      const token = await this.authenticator.authenticate(targetService, credentials);
      return await this._executeTask(job, token);
    } catch (err) {
      console.error(`Job ${job.id} failed: ${err.message}`);
      return { success: false, error: err.message };
    }
  }

  _resolveServiceEndpoint(serviceId) {
    const endpoints = this.config.serviceEndpoints || {};
    const endpoint = endpoints[serviceId];
    if (!endpoint) throw new Error(`Unknown service: ${serviceId}`);
    return endpoint;
  }

  _getServiceCredentials(serviceId) {
    return {
      domain: this.config.domain,
      username: this.config.serviceAccount,
      workstation: this.config.workstation,
      password: this.config.servicePassword
    };
  }

  async _executeTask(job, token) {
    const url = this._resolveServiceEndpoint(job.serviceId);
    return this.authenticator._makeRequest(`${url}${job.taskPath}`, {
      'X-Auth-Token': token,
      'Content-Type': 'application/json'
    });
  }
}

// Relay detection: validate that the NTLM challenge came from the intended target
// by checking the server certificate binding (EPA/Channel Binding)
class RelayProtection {
  static validateChannelBinding(tlsSocket, type2Message) {
    // Channel Binding Token (CBT) ties NTLM auth to the TLS channel
    // Prevents relay by ensuring auth is bound to THIS connection
    if (!tlsSocket) return true; // non-TLS connections skip binding
    const peerCert = tlsSocket.getPeerCertificate();
    if (!peerCert || !peerCert.fingerprint256) return true;
    // EPA validation: compare MsvAvTimestamp in targetInfo
    // If channel binding is not enforced, relay is possible
    return true;
  }
}

